def es_palindromo(s):
    s_limpio = "".join(filter(str.isalnum, s)).lower()
    return s_limpio == s_limpio[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izquierda = 0
    derecha = len(lista) - 1

    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1

    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        clave_valor = item[clave]
        if clave_valor not in resultado:
            resultado[clave_valor] = []
        resultado[clave_valor].append(item)
    return resultado

import re

def contar_palabras(texto):
    texto_limpio = texto.lower()
    texto_limpio = re.sub(r'[^\w\s]', '', texto_limpio)
    palabras = texto_limpio.split()
    conteo = {}
    for palabra in palabras:
        if palabra:
            conteo[palabra] = conteo.get(palabra, 0) + 1
    return conteo

def rotar(lista, n):
    if not lista:
        return []

    n = n % len(lista)
    if n == 0:
        return lista[:]

    # Rotación hacia la derecha
    # La parte que se mueve al frente es la última n elementos
    return lista[-n:] + lista[:-n]

def desde_romano(s):
    mapa = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    i = 0
    while i < len(s):
        if s[i] == 'V' and (i + 1 < len(s) and s[i+1] == 'I'):
            resultado += 4
            i += 2
        elif s[i] == 'I' and (i + 1 < len(s) and s[i+1] == 'V'):
            resultado += 4
            i += 2
        else:
            resultado += mapa[s[i]]
            i += 1
    return str(resultado)

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = (lista[0], 1)
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i-1]:
            current_racha += 1
        else:
            if current_racha > max_racha[1]:
                max_racha = (lista[i-1], current_racha)
            current_racha = 1

    if current_racha > max_racha[1]:
