def primos(n):
    if n < 2:
        return []

    es_primo = [True] * (n + 1)
    es_primo[0] = es_primo[1] = False

    for p in range(2, int(n**0.5) + 1):
        if es_primo[p]:
            for i in range(p * p, n + 1, p):
                es_primo[i] = False

    resultado = []
    for i in range(2, n + 1):
        if es_primo[i]:
            resultado.append(i)

    return resultado

def mcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    while b:
        a, b = b, a % b
    return a

def comprimir(s):
    if not s:
        return s

    comprimido = []
    i = 0
    while i < len(s):
        current_char = s[i]
        count = 0
        j = i
        while j < len(s) and s[j] == current_char:
            count += 1
            j += 1

        if count > 1:
            comprimido.append(current_char + str(count))
        else:
            comprimido.append(current_char)

        i = j

    resultado = "".join(comprimido)

    if len(resultado) < len(s):
        return resultado
    else:
        return s

def balanceado(texto):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in texto:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False

    return not stack

