def mediana(nums):
    if not nums:
        return None

    nums.sort()
    n = len(nums)

    if n % 2 == 1:
        return nums[n // 2]
    else:
        mid1 = nums[n // 2 - 1]
        mid2 = nums[n // 2]
        return (mid1 + mid2) / 2

