def promedio_movil(nums, ventana):
    if len(nums) < ventana:
        return []

    resultados = []
    suma_actual = sum(nums[:ventana])
    resultados.append(suma_actual / ventana)

    for i in range(ventana, len(nums)):
        suma_actual = suma_actual - nums[i - ventana] + nums[i]
        resultados.append(suma_actual / ventana)

    return resultados

def formatear_bytes(n):
    if n == 0:
        return "0 B"

    labels = ["B", "KB", "MB", "GB"]

    # Determinar la unidad
    unit_index = 0
    while n >= 1024 and unit_index < len(labels) - 1:
        n /= 1024
        unit_index += 1

    # Formatear el número
    if unit_index == 0:
        # Bytes sin decimales
        return f"{n:.0f} {labels[0]}"
    else:
        # Otros casos con un decimal
        return f"{n:.1f} {labels[unit_index]}"

def parsear_query(s):
    if not s:
        return {}

    result = {}
    pairs = s.split('&')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            result[key] = value
        else:
            # Caso de clave sin valor, ej: 'c=' o solo 'c' si se interpreta como clave sin signo
            # Basado en el ejemplo 'c=' -> {'c': ''}
            key = pair
            result[key] = ""

    return result

def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    island_count = 0

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or visited[r][c] or grid[r][c] == 0:
            return
        visited[r][c] = True
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                island_count += 1
                dfs(r, c)
    return island_count

def distancia(s1, s2):
    n = len(s1)
    m = len(s2)

    # Inicializar la matriz de costos
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Inicializar la primera fila y columna
    for i in range(n + 1):
        dp[i][0] = i  # Costo de borrar i caracteres de s1 para obtener s2 vacío
    for j in range(m + 1):
        dp[0][j] = j  # Costo de insertar j caracteres en s1 vacío para obtener s2

    # Llenar la matriz
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1

            dp[i][j] = min(
                dp[i - 1][j] + 1,        # Borrado (Deletion)
                dp[i][j - 1] + 1,        # Inserción (Insertion)
                dp[i - 1][j - 1] + cost  # Sustitución o coincidencia (Substitution/Match)
            )

    return dp[n][m]

def validar_password(p):
    if len(p) < 8:
        return False
    if not any(p.isupper()):
        return False
    if not any(p.islower()):
        return False
    if not any(p.isdigit()):
        return False
    if not any(not char.isalnum() for char in p):
        return False
    return True

def a_base(n, base):
    if n == 0:
        return '0'

    digits = "0123456789abcdef"
    result = ""

    while n > 0:
        remainder = n % base
        result = digits[remainder] + result
        n //= base

    return result

