def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista

    nueva_lista = []
    for elemento in lista:
        if isinstance(elemento, list):
            if profundidad > 0:
                aplanada = aplanar_hasta(elemento, profundidad - 1)
                nueva_lista.extend(aplanada)
            else:
                # Si la profundidad es 0, no aplanamos el nivel, mantenemos la lista original
                # Esto implica que si encontramos una lista a la profundidad 0, la añadimos como está.
                # Sin embargo, el requisito es "aplanar solo hasta la profundidad indicada".
                # Si la profundidad es 1, aplanamos el nivel actual.
                # Si la profundidad es 0, no hacemos nada con esa lista.
                # Para la lógica de aplanamiento, si profundidad > 0, recursivamente aplanamos.
                # Si profundidad == 0, la lista se mantiene como está en este nivel.
                nueva_lista.append(elemento)
        else:
            nueva_lista.append(elemento)
    return nueva_lista

def sumar_romanos(a, b):
    def romano_a_decimal(s):
        roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        decimal_value = 0
        for char in s:
            decimal_value += roman_map[char]
        return decimal_value

    def decimal_a_romano(n):
        if n == 0:
            return "0"
        roman_map = {
            1000: 'M', 900: 'CM', 500: 'D', 400: 'CD', 100: 'C', 90: 'XC', 50: 'L', 40: 'XL', 10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'
        }
        result = ""
        for value, symbol in roman_map.items():
            while n >= value:
                result += symbol
                n -= value
        return result

    decimal_a = romano_a_decimal(a) + romano_a_decimal(b)
    return decimal_a_romano(decimal_a)

def obtener(d, camino, defecto=None):
    """
    Busca en un dict anidado siguiendo un camino con puntos ('a.b.c') y devuelve el valor, 
    o el defecto si algún tramo no existe.
    """
    if not camino:
        return d

    current = d
    path_segments = camino.split('.')

    for segment in path_segments:
        if isinstance(current, dict) and segment in current:
            current = current[segment]
        else:
            return defecto

    return current

def con_reintentos(fn, veces):
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            if i < veces - 1:
                continue
            else:
                raise e
